(function(root){
const clues={
 door:{title:'Locked from within',type:'PHYSICAL',text:'The office door is bolted from the inside. Its lock takes a large brass key; the missing small silver key cannot open it. Nobody has disturbed the bolt.'},
 window:{title:'Unbroken rain',type:'PHYSICAL',text:'The window is latched. Dust on the inner sill is undisturbed, and rain has left no wet footprints below it. This was not the escape route.'},
 wound:{title:'A narrow wound',type:'PHYSICAL',text:'Vale lies beside the desk. A narrow puncture and a dark stain mark his tactical vest. The desk’s steel letter opener is missing. The scene suggests a close-range attack, not an accident.'},
 key:{title:'The borrowed key',type:'TIME',text:'10:03 — a small silver key sits on the desk. 10:06 — the visitor lifts it. A split-ring insignia on its bow matches the bookshelf’s concealed latch. This key opens a passage, not the office door.'},
 clock:{title:'Nine minutes, not twelve',type:'TIME',text:'At 10:09, Vale falls and the visitor advances the wall clock to 10:12, then stops its pendulum. The temporal echo continues to read 10:09. The apparent time of death was deliberately falsified.'},
 trail:{title:'A broken left heel',type:'SHADOW',text:'At 10:09, a shadow trail leads from the desk to the bookshelf. Every left footprint has a crescent-shaped gap at the heel. A concealed figure disappears through the shelf, carrying something small and silver.'},
 passage:{title:'The service passage',type:'SHADOW',text:'At 10:06 or 10:09, the shadow of the shelf reveals a hinged panel with a split-ring latch. Fresh scratches show it was opened tonight. The narrow passage leads to the west maintenance stair.'},
 fire:{title:'The ninth-minute instruction',type:'FIRE',text:'Recovered from ash: “At the ninth minute, take the silver key. Use the split-ring service latch. Return through the west stair; leave the office bolt untouched.” A split-ring sketch sits beneath the text. The note describes a planned escape and was burned after 10:09.'},
 roster:{title:'The west-stair ledger',type:'FIRE',text:'Heat reveals erased pressure marks on the charred access ledger: “M. Rook — west stair, 22:05–22:11.” A repair note reads: “left boot heel chipped; replace Monday.” Only this access entry overlaps the attack.'},
 ribbon:{title:'A red ribbon',type:'PHYSICAL',text:'A red silk ribbon lies beside the desk. On its paper band: “Dr. Lena Voss — lecture gift, yesterday.” It belongs to Voss, but predates tonight’s visit.'},
 receipt:{title:'A collector’s receipt',type:'PHYSICAL',text:'A receipt signed by Elias Thorn records a visit at 21:20 to discuss buying Vale’s research. A matching lobby departure stamp reads 21:35. It places him here earlier, not at the ninth minute.'}
};
const suspects=[
{id:'voss',name:'Dr. Lena Voss',role:'RESEARCH OFFICER / VOSS',initials:'LV',motive:'Vale planned to publish their joint research under his name alone.',alibi:'“I was in the east laboratory from ten until quarter past.”',opportunity:'She knows the office and visited yesterday.',mislead:'Her red ribbon was found near the desk.',links:['ribbon','clock']},
{id:'rook',name:'Mara Rook',role:'COMBAT ENGINEER / ROOK',initials:'MR',motive:'Vale had discovered falsified maintenance invoices and planned to dismiss her.',alibi:'“I was in the boiler room from ten until quarter past. I never used the west stair.”',opportunity:'Her work gives her knowledge of the building’s service routes.',mislead:'Her maintenance tools could account for old marks on the shelf.',links:['trail','roster','passage']},
{id:'thorn',name:'Elias Thorn',role:'PRIVATE CONTRACTOR / THORN',initials:'ET',motive:'Vale refused to sell a temporal prototype after taking Thorn’s advance.',alibi:'“I left the estate well before ten.”',opportunity:'He was admitted to the office earlier in the evening.',mislead:'His receipt is still on Vale’s desk.',links:['receipt','door']}
];
const rules=[{id:'when',needs:['key','clock'],title:'The fatal ninth minute',text:'The attack occurred at 10:09. The visitor took the service key earlier and falsified the clock to read 10:12.'},{id:'route',needs:['passage','fire'],title:'A locked door, an open route',text:'The burned plan and concealed latch identify the service passage as the escape. The silver key opens it while the office stays bolted.'},{id:'who',needs:['trail','roster'],title:'The alibi that cannot hold',text:'The damaged left heel matches the west-stair ledger’s repair note. Rook’s recorded movement overlaps the attack and contradicts her boiler-room alibi.'}];
function fresh(){return {time:3,mode:'normal',evidence:[],deductions:[],selected:[],ending:null};}
function available(s,obj){if(obj==='door')return 'door';if(obj==='window')return 'window';if(obj==='body')return s.time>=2?'wound':null;if(obj==='desk')return 'ribbon';if(obj==='receipt')return 'receipt';if(obj==='key')return s.time===1?'key':null;if(obj==='clock')return s.time===2?'clock':null;if(obj==='trail')return s.mode==='shadow'&&s.time===2?'trail':null;if(obj==='shelf')return s.mode==='shadow'&&(s.time===1||s.time===2)?'passage':null;if(obj==='fireplace')return s.mode==='fire'&&s.time===3?'fire':null;if(obj==='ledger')return s.mode==='fire'&&s.time===3?'roster':null;return null;}
function collect(s,id){if(!clues[id]||s.evidence.includes(id))return false;s.evidence.push(id);return true;}
function connect(s,ids){if(ids.length!==2||new Set(ids).size!==2||!ids.every(id=>s.evidence.includes(id)))return null;const r=rules.find(r=>r.needs.every(id=>ids.includes(id)));if(!r)return null;if(!s.deductions.includes(r.id))s.deductions.push(r.id);return r;}
function accuse(s,id){if(s.deductions.length<3)return 'incomplete';if(!suspects.some(x=>x.id===id))return 'invalid';s.ending=id==='rook'?'solved':'incorrect';return s.ending;}
const api={clues,suspects,rules,fresh,available,collect,connect,accuse};if(typeof module!=='undefined')module.exports=api;root.Mystery=api;
})(typeof window!=='undefined'?window:globalThis);
